record.field:
for rec in records:
    if rec.is_outdated_bom and rec.state in ("draft", "confirm"):
        rec.action_update_bom()

for batch in records:
    if not batch.date_start or not batch.workcenter_tag_id:
        continue  # Skip if essential fields are missing

    # Convert date_start to a date-only format
    schedule_date = batch.date_start.date()

    # Find an existing schedule for this date and workcenter tag
    schedule = env["mrp.production.batch.schedule"].search([
        ("date", "=", schedule_date),
        ("workcenter_tag_id", "=", batch.workcenter_tag_id.id),
        ("company_id", "=", batch.company_id.id),
    ], limit=1)

    # If no schedule exists, create one
    if not schedule:
        schedule = env["mrp.production.batch.schedule"].create({
            "date": schedule_date,
            "workcenter_tag_id": batch.workcenter_tag_id.id,
            "company_id": batch.company_id.id or env.company,
        })

    # # Assign the schedule to the batch
    batch.write({"mrp_batch_schedule_id": schedule.id})
